local PigmentGrinderMaker = {}
local PRODUCTS = {
    iron_pigment_grinder = { name = "Železni mlinček za pigmente", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 175, prestige = 3, happiness = 2, description = "Železni mlinček za drobljenje pigmentov." },
    bronze_pigment_grinder = { name = "Bronast mlinček za pigmente", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 425, prestige = 5, happiness = 3, description = "Bronast mlinček za finje pigmente." },
    silver_pigment_grinder = { name = "Srebrni mlinček za pigmente", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1025, prestige = 10, happiness = 4, description = "Srebrni mlinček za plemiške slikarje." },
    gilded_pigment_grinder = { name = "Pozlačeni mlinček za pigmente", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2200, prestige = 19, happiness = 5, description = "Pozlačeni mlinček za dvorne slikarje." },
    jewel_set_pigment_grinder = { name = "Draguljasti mlinček za pigmente", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4750, prestige = 35, happiness = 7, description = "Draguljasti mlinček za kraljeve slikarje." },
    royal_sovereign_pigment_grinder = { name = "Kraljevski suvereni mlinček za pigmente", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suvereni mlinček z biseri za krono." },
}
local BUILDINGS = {
    pigment_workshop = { name = "Pigmentna delavnica", cost = { gold = 350, wood = 175, stone = 140, iron = 9 }, upkeep = 6, qualityBonus = 5 },
    pigment_house = { name = "Pigmentna hiša", cost = { gold = 1240, wood = 355, stone = 275, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_pigment_atelier = { name = "Mojstrski pigmentni atelje", cost = { gold = 3100, wood = 415, stone = 530, silver = 37, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_pigment_palace = { name = "Suverena pigmentna palača", cost = { gold = 13200, wood = 635, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
PigmentGrinderMaker.ironStock = 14; PigmentGrinderMaker.bronzeStock = 12; PigmentGrinderMaker.woodStock = 12; PigmentGrinderMaker.leatherStock = 10; PigmentGrinderMaker.silverStock = 8; PigmentGrinderMaker.goldStock = 6; PigmentGrinderMaker.jewelStock = 4; PigmentGrinderMaker.pearlStock = 4
PigmentGrinderMaker.productStock = {}; PigmentGrinderMaker.buildings = {}; PigmentGrinderMaker.maker = nil; PigmentGrinderMaker.activeMaking = {}; PigmentGrinderMaker.totalProducts = 0; PigmentGrinderMaker.dayTimer = 0
function PigmentGrinderMaker.init() PigmentGrinderMaker.ironStock=14; PigmentGrinderMaker.bronzeStock=12; PigmentGrinderMaker.woodStock=12; PigmentGrinderMaker.leatherStock=10; PigmentGrinderMaker.silverStock=8; PigmentGrinderMaker.goldStock=6; PigmentGrinderMaker.jewelStock=4; PigmentGrinderMaker.pearlStock=4; PigmentGrinderMaker.productStock={}; PigmentGrinderMaker.buildings={}; PigmentGrinderMaker.maker=nil; PigmentGrinderMaker.activeMaking={}; PigmentGrinderMaker.totalProducts=0; PigmentGrinderMaker.dayTimer=0; print("[PigmentGrinderMaker] Royal Pigment Grinder Maker System initialized (6 products, 4 buildings)") end
function PigmentGrinderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PigmentGrinderMaker.maker={name=n or ("Pigmentar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pigmentar najet: %s (spretnost: %d)",PigmentGrinderMaker.maker.name,s),"success") end; return true end
function PigmentGrinderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PigmentGrinderMaker.build(id) local ok,e=PigmentGrinderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PigmentGrinderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PigmentGrinderMaker.getQualityBonus() local b=0; for _,bd in ipairs(PigmentGrinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PigmentGrinderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PigmentGrinderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PigmentGrinderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PigmentGrinderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PigmentGrinderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PigmentGrinderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PigmentGrinderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PigmentGrinderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PigmentGrinderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PigmentGrinderMaker.buildings==0 then return false,"Potrebna pigmentna delavnica" end; if not PigmentGrinderMaker.maker then return false,"Potreben pigmentar" end; return true end
function PigmentGrinderMaker.make(pt,qty) qty=qty or 1; local ok,e=PigmentGrinderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PigmentGrinderMaker.ironStock=PigmentGrinderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PigmentGrinderMaker.bronzeStock=PigmentGrinderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PigmentGrinderMaker.woodStock=PigmentGrinderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PigmentGrinderMaker.leatherStock=PigmentGrinderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PigmentGrinderMaker.silverStock=PigmentGrinderMaker.silverStock-d.silverCost*qty end; if d.goldCost then PigmentGrinderMaker.goldStock=PigmentGrinderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PigmentGrinderMaker.jewelStock=PigmentGrinderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PigmentGrinderMaker.pearlStock=PigmentGrinderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PigmentGrinderMaker.maker then t=math.max(1,t-math.floor(PigmentGrinderMaker.maker.skill/13)) end; table.insert(PigmentGrinderMaker.activeMaking,{id="pigment_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PigmentGrinderMaker.completeMaking(m) local q=1.0+(PigmentGrinderMaker.getQualityBonus()/100); if PigmentGrinderMaker.maker then q=q+(PigmentGrinderMaker.maker.skill/140) end; q=math.min(2.5,q); PigmentGrinderMaker.productStock[m.productType]=(PigmentGrinderMaker.productStock[m.productType] or 0)+m.quantity; PigmentGrinderMaker.totalProducts=PigmentGrinderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PigmentGrinderMaker.maker then PigmentGrinderMaker.maker.itemsMade=PigmentGrinderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PigmentGrinderMaker.maker.skill=math.min(100,PigmentGrinderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlinček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pigment.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PigmentGrinderMaker.update(dt) if not _G.state then return end; PigmentGrinderMaker.dayTimer=PigmentGrinderMaker.dayTimer+dt; if PigmentGrinderMaker.dayTimer>=30 then PigmentGrinderMaker.dayTimer=0; for i=#PigmentGrinderMaker.activeMaking,1,-1 do local m=PigmentGrinderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PigmentGrinderMaker.completeMaking(m); table.remove(PigmentGrinderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PigmentGrinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PigmentGrinderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PigmentGrinderMaker.getStats() return {ironStock=PigmentGrinderMaker.ironStock,bronzeStock=PigmentGrinderMaker.bronzeStock,woodStock=PigmentGrinderMaker.woodStock,leatherStock=PigmentGrinderMaker.leatherStock,silverStock=PigmentGrinderMaker.silverStock,goldStock=PigmentGrinderMaker.goldStock,jewelStock=PigmentGrinderMaker.jewelStock,pearlStock=PigmentGrinderMaker.pearlStock,productStock=PigmentGrinderMaker.productStock,numBuildings=#PigmentGrinderMaker.buildings,hasMaker=PigmentGrinderMaker.maker~=nil,makerName=PigmentGrinderMaker.maker and PigmentGrinderMaker.maker.name or "—",makerSkill=PigmentGrinderMaker.maker and PigmentGrinderMaker.maker.skill or 0,activeMaking=#PigmentGrinderMaker.activeMaking,totalProducts=PigmentGrinderMaker.totalProducts} end
return PigmentGrinderMaker
